-- Stocktake workflow: create a draft, submit it for approval, then apply the
-- approved quantities to TON_KHO in one transaction.
-- Apply after migrations 001-008.

create table if not exists public."PHIEU_KIEM_KE" (
  "ma_phieu_kiem" int generated by default as identity primary key,
  "ma_phieu_code" varchar not null unique,
  "ma_kho" int not null references public."KHO" ("ma_kho"),
  "ngay_tao" timestamptz not null default now(),
  "trang_thai" varchar not null default 'NHAP',
  "nguoi_tao" varchar not null references public."NHAN_VIEN" ("ma_nhan_vien"),
  "nguoi_duyet" varchar references public."NHAN_VIEN" ("ma_nhan_vien"),
  "ngay_duyet" timestamptz,
  "ghi_chu" text,
  check ("trang_thai" in ('NHAP', 'CHO_DUYET', 'DA_DUYET', 'TU_CHOI'))
);

create table if not exists public."CT_KIEM_KE" (
  "ma_phieu_kiem" int not null references public."PHIEU_KIEM_KE" ("ma_phieu_kiem") on delete cascade,
  "sku" varchar not null references public."SAN_PHAM" ("sku"),
  "so_luong_he_thong" int not null check ("so_luong_he_thong" >= 0),
  "so_luong_thuc_te" int not null check ("so_luong_thuc_te" >= 0),
  "chenh_lech" int generated always as ("so_luong_thuc_te" - "so_luong_he_thong") stored,
  primary key ("ma_phieu_kiem", "sku")
);

create index if not exists "idx_phieu_kiem_kho_status"
  on public."PHIEU_KIEM_KE" ("ma_kho", "trang_thai", "ngay_tao" desc);

create or replace function public.create_stocktake_draft(
  p_ma_kho integer,
  p_nguoi_tao varchar,
  p_ghi_chu text,
  p_lines jsonb
)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  stocktake_id integer;
  code varchar;
  line_row record;
  current_quantity integer;
begin
  if not exists (select 1 from public."KHO" where "ma_kho" = p_ma_kho and "trang_thai" = 1) then
    raise exception using errcode = 'P0090', message = 'WAREHOUSE_NOT_FOUND';
  end if;
  if not exists (select 1 from public."NHAN_VIEN" where "ma_nhan_vien" = p_nguoi_tao and "trang_thai" = 1) then
    raise exception using errcode = 'P0091', message = 'CREATOR_NOT_FOUND';
  end if;
  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception using errcode = 'P0092', message = 'STOCKTAKE_HAS_NO_LINES';
  end if;

  code := 'KK-' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISSMS') || '-' || floor(random() * 1000)::int;
  insert into public."PHIEU_KIEM_KE" ("ma_phieu_code", "ma_kho", "nguoi_tao", "ghi_chu")
  values (code, p_ma_kho, p_nguoi_tao, p_ghi_chu)
  returning "ma_phieu_kiem" into stocktake_id;

  for line_row in select * from jsonb_to_recordset(p_lines) as x(sku varchar, counted_quantity integer) loop
    if line_row.counted_quantity is null or line_row.counted_quantity < 0 then
      raise exception using errcode = 'P0093', message = 'INVALID_COUNTED_QUANTITY';
    end if;
    if not exists (select 1 from public."SAN_PHAM" where "sku" = line_row.sku and "trang_thai" = 1) then
      raise exception using errcode = 'P0094', message = 'PRODUCT_NOT_FOUND';
    end if;
    select coalesce("so_luong_ton", 0) into current_quantity
      from public."TON_KHO" where "ma_kho" = p_ma_kho and "sku" = line_row.sku;
    insert into public."CT_KIEM_KE" ("ma_phieu_kiem", "sku", "so_luong_he_thong", "so_luong_thuc_te")
    values (stocktake_id, line_row.sku, coalesce(current_quantity, 0), line_row.counted_quantity);
  end loop;
  return jsonb_build_object('ma_phieu_kiem', stocktake_id, 'ma_phieu_code', code, 'trang_thai', 'NHAP');
end; $$;

create or replace function public.submit_stocktake(p_ma_phieu_kiem integer)
returns jsonb language plpgsql security definer set search_path = public as $$
declare current_status varchar;
begin
  select "trang_thai" into current_status from public."PHIEU_KIEM_KE" where "ma_phieu_kiem" = p_ma_phieu_kiem for update;
  if not found then raise exception using errcode = 'P0095', message = 'STOCKTAKE_NOT_FOUND'; end if;
  if current_status <> 'NHAP' then raise exception using errcode = 'P0096', message = 'STOCKTAKE_NOT_EDITABLE'; end if;
  update public."PHIEU_KIEM_KE" set "trang_thai" = 'CHO_DUYET' where "ma_phieu_kiem" = p_ma_phieu_kiem;
  return jsonb_build_object('ma_phieu_kiem', p_ma_phieu_kiem, 'trang_thai', 'CHO_DUYET');
end; $$;

create or replace function public.approve_stocktake(p_ma_phieu_kiem integer, p_nguoi_duyet varchar)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  header_row record;
  line_row record;
  previous_quantity integer;
begin
  select * into header_row from public."PHIEU_KIEM_KE" where "ma_phieu_kiem" = p_ma_phieu_kiem for update;
  if not found then raise exception using errcode = 'P0095', message = 'STOCKTAKE_NOT_FOUND'; end if;
  if header_row."trang_thai" <> 'CHO_DUYET' then raise exception using errcode = 'P0097', message = 'STOCKTAKE_NOT_SUBMITTED'; end if;
  if not exists (select 1 from public."NHAN_VIEN" where "ma_nhan_vien" = p_nguoi_duyet and "loai_nhan_vien" = 'ADMIN' and "trang_thai" = 1) then
    raise exception using errcode = 'P0098', message = 'APPROVER_NOT_ALLOWED';
  end if;

  perform set_config('phub.stock_operation', 'KIEM_KE', true);
  perform set_config('phub.stock_reference', header_row."ma_phieu_code", true);
  perform set_config('phub.stock_actor', p_nguoi_duyet, true);
  for line_row in select * from public."CT_KIEM_KE" where "ma_phieu_kiem" = p_ma_phieu_kiem loop
    select "so_luong_ton" into previous_quantity from public."TON_KHO"
      where "ma_kho" = header_row."ma_kho" and "sku" = line_row."sku" for update;
    if found then
      update public."TON_KHO" set "so_luong_ton" = line_row."so_luong_thuc_te", "cap_nhat_luc" = now()
        where "ma_kho" = header_row."ma_kho" and "sku" = line_row."sku";
    else
      insert into public."TON_KHO" ("ma_kho", "sku", "so_luong_ton", "cap_nhat_luc")
      values (header_row."ma_kho", line_row."sku", line_row."so_luong_thuc_te", now());
      insert into public."LICH_SU_TON_KHO" ("ma_kho", "sku", "loai_giao_dich", "so_luong_thay_doi", "so_luong_truoc", "so_luong_sau", "ma_tham_chieu", "nguoi_thuc_hien")
      values (header_row."ma_kho", line_row."sku", 'KIEM_KE', line_row."so_luong_thuc_te", 0, line_row."so_luong_thuc_te", header_row."ma_phieu_code", p_nguoi_duyet);
    end if;
  end loop;
  update public."PHIEU_KIEM_KE" set "trang_thai" = 'DA_DUYET', "nguoi_duyet" = p_nguoi_duyet, "ngay_duyet" = now()
    where "ma_phieu_kiem" = p_ma_phieu_kiem;
  return jsonb_build_object('ma_phieu_kiem', p_ma_phieu_kiem, 'trang_thai', 'DA_DUYET');
end; $$;

revoke all on function public.create_stocktake_draft(integer, varchar, text, jsonb) from public, anon, authenticated;
revoke all on function public.submit_stocktake(integer) from public, anon, authenticated;
revoke all on function public.approve_stocktake(integer, varchar) from public, anon, authenticated;
grant execute on function public.create_stocktake_draft(integer, varchar, text, jsonb) to service_role;
grant execute on function public.submit_stocktake(integer) to service_role;
grant execute on function public.approve_stocktake(integer, varchar) to service_role;

alter table public."PHIEU_KIEM_KE" enable row level security;
alter table public."CT_KIEM_KE" enable row level security;
revoke all on table public."PHIEU_KIEM_KE", public."CT_KIEM_KE" from anon, authenticated;
grant all on table public."PHIEU_KIEM_KE", public."CT_KIEM_KE" to service_role;
